package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.special.Beta;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for getInitialDomain method in FDistributionImpl.
 * Since the method is protected, we use reflection to access it.
 */
public class FDistributionImpl_getInitialDomain_TriageGen2Test {

    /**
     * Helper method to invoke the protected method getInitialDomain via reflection.
     */
    private double invokeGetInitialDomain(FDistributionImpl distribution, double p) throws Exception {
        Method method = FDistributionImpl.class.getDeclaredMethod("getInitialDomain", double.class);
        method.setAccessible(true);
        return (double) method.invoke(distribution, p);
    }

    @Test
    public void testGetInitialDomain_StandardCase() throws Exception {
        // Setup: denominator degrees of freedom = 10.0
        double numeratorDf = 5.0;
        double denominatorDf = 10.0;
        FDistributionImpl distribution = new FDistributionImpl(numeratorDf, denominatorDf);

        // Calculation: d / (d - 2.0) => 10.0 / (10.0 - 2.0) = 10.0 / 8.0 = 1.25
        double expected = 1.25;
        double actual = invokeGetInitialDomain(distribution, 0.5);

        Assert.assertEquals("The initial domain calculation for d=10 should be 1.25", expected, actual, 1e-10);
    }








}

